INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6788, 'Drh2H#xJo!', 3325956113, 1570825887, 0, ' level39 radical ', 'hill岡This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">hill</span>.5948', 'hill', 1558824159, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6789, 'lSI[wQB:`d', 3325956113, 1570825887, 0, ' level39 radical ', 'nurse㐮This radical is made up of blackjack and clothes with the six kanji on top. If you see six people playing blackjack and wearing the same clothes you should know that they''re all <span class="radical-highlight" title="Radical" rel="tooltip">nurse</span>s. Nurses play blackjack together to cool down between shifts and they usually don''t have time to change out of their uniforms. That''s why this radical is nurse.5949', 'nurse', 677353984, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6790, 'dl$~udQf?&', 3325956113, 1570825887, 0, ' level39 radical ', 'reality真This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">reality</span>.5950', 'reality', 500458540, 0, '');
