INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6797, 'rqWG;0D|Sv', 3325956113, 1570825887, 0, ' level41 radical ', 'cactusSee the <span class="radical-highlight" title="Radical" rel="tooltip">cactus</span> coming out of the ground? It''s happy to see you!<i class="radical-cactus"></i>6244', 'cactus', 3287184891, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6798, 'Fl.f5w)x%w', 3325956113, 1570825887, 0, ' level41 radical ', 'signpost夆This is a post with signs on it. And on top is a winter marker, showing that if you go north it''s winter up there. The signs say things like "Narnia ↑" and "Meridell ←" and "Bananaland →" so you know it''s a <span class="radical-highlight" title="Radical" rel="tooltip">signpost</span>.6245', 'signpost', 2495572943, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6799, 'sJptV@En{_', 3325956113, 1570825887, 0, ' level41 radical ', 'wife妻This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">wife</span>.6246', 'wife', 1223534387, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6800, 'cbev&)x|)2', 3325956113, 1570825887, 0, ' level42 radical ', 'bone骨This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">bone</span>.6392', 'bone', 4292824267, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6801, 'sYtiMV`K0C', 3325956113, 1570825887, 0, ' level42 radical ', 'melon瓜This is a <span class="radical-highlight" title="Radical" rel="tooltip">melon</span>. Imagine a melon cut in half, and you''re looking at its insides from the side. See those precious private melon parts? You''re gonna keep those for yourself, because melons are delicious and not for sharing.6393', 'melon', 3586301296, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6802, 'MF|mFg|YYJ', 3325956113, 1572474450, 0, ' level42 radical ', 'satellite<img src="satellite.png" />Look at this radical. Can you see it floating in space? Can you see the antennae and reflectors? That''s because it''s a <span class="radical-highlight" title="Radical" rel="tooltip">satellite</span>.6394', 'satellite', 908669440, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6803, 'u&uAN$SsN@', 3325956113, 1570825887, 0, ' level42 radical ', 'shop屋We already have a roof radical, so we''re going to use the secondary kanji meaning for this radical. It''s <span class="radical-highlight" title="Radical" rel="tooltip">shop</span>, remember?6395', 'shop', 1346556230, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6804, 'kl]TeNe@M~', 3325956113, 1570825887, 0, ' level43 radical ', 'badger豸You know the animal radical. This is just like that with a little extra. It''s an animal already... which means all you have to do is remember what kind of animal. In this case, it''s a <span class="radical-highlight" title="Radical" rel="tooltip">badger</span>.6527', 'badger', 1310301002, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6805, 'v>{in8!u6j', 3325956113, 1570825887, 0, ' level43 radical ', 'imperial龍Stand up on the moon so you can look down on your countries. The thing with all the lines and borders are the borders of all the countries you rule, for you are an <span class="radical-highlight" title="Radical" rel="tooltip">imperial</span>.6528', 'imperial', 1732543575, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6806, 'L~l|UOrVIP', 3325956113, 1570825887, 0, ' level43 radical ', 'plow耒You''re sliding some dirt around with a tree you cut down. This contraption you''ve made is called a <span class="radical-highlight" title="Radical" rel="tooltip">plow</span>. Use it to push dirt around!6529', 'plow', 4206662035, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6807, 't,{QclzE{>', 3325956113, 1570825887, 0, ' level44 radical ', 'can缶It''s kind of hard to see, but if you look at this the right way it looks like a tin <span class="radical-highlight" title="Radical" rel="tooltip">can</span>. The lines in the middle show the circumference, and the lines on the tops and sides show the outline of the can.6678', 'can', 2123504032, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6808, 'md=p_{.rjf', 3325956113, 1570825887, 0, ' level44 radical ', 'dragon竜A turtle that stands up isn''t a turtle anymore. It''s evolved into a monster. What kind of monster? A <span class="radical-highlight" title="Radical" rel="tooltip">dragon</span>! Rawwwr.6679', 'dragon', 2945022129, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6809, 'v0*rh}h:kK', 3325956113, 1570825887, 0, ' level44 radical ', 'wind風This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">wind</span>.6680', 'wind', 3875574247, 0, '');
