INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6815, 'x4Q6gEXyL)', 3325956113, 1570825887, 0, ' level47 radical ', 'penguin敝There are fins wrapped in a towel in winter. Who is drying these fish fins to eat them? A <span class="radical-highlight" title="Radical" rel="tooltip">penguin</span>.7102', 'penguin', 1932745762, 0, '');
