INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6818, 'u@9v|Q1JaF', 3325956113, 1570825887, 0, ' level48 radical ', 'mysterious玄What''s under this lid that smells like poop? I don''t know! How <span class="radical-highlight" title="Radical" rel="tooltip">mysterious</span>.7235', 'mysterious', 994166702, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6819, 'O9@#)V,jcR', 3325956113, 1570825887, 0, ' level48 radical ', 'sunlight光This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">sunlight</span>.7236', 'sunlight', 525000775, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6820, 'jgiI;xx_7T', 3325956113, 1570825887, 0, ' level49 radical ', 'crab trap甚This radical looks like a small animal (<span lang="ja">匹</span>) has a crab (<span lang="ja">其</span>) sticking out of it. Often when a crab is eating a small animal, that small animal was put inside a crab trap to catch the crab, luring it in with the small animal. That''s why this radical is <span class="radical-highlight" title="Radical" rel="tooltip">crab trap</span>.7379', 'crab trap', 2399821921, 0, '');
INSERT INTO notes (id, guid, mid, mod, usn, tags, flds, sfld, csum, flags, data) VALUES (6821, 'mrjqXQ*`x;', 3325956113, 1570825887, 0, ' level49 radical ', 'times回This radical is the same as the kanji. It means <span class="radical-highlight" title="Radical" rel="tooltip">times</span>.7380', 'times', 1905702279, 0, '');
